use std::collections::BTreeMap;
use std::ops::{AddAssign};

use crate::language_type::LanguageType;

/// Statistics about a piece of code (a file or an embedded blob).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct CodeStats {
    pub blanks: usize,
    pub code: usize,
    pub comments: usize,
    pub blobs: BTreeMap<LanguageType, CodeStats>,
}

impl CodeStats {
    pub fn new() -> Self {
        Self::default()
    }

    /// Total lines of this blob (not including embedded blobs).
    pub fn lines(&self) -> usize {
        self.blanks + self.code + self.comments
    }

    /// Produces a copy of these stats where every embedded blob has been
    /// folded into the top level numbers.
    pub fn summarise(&self) -> CodeStats {
        let mut summary = self.clone();
        for (_, stats) in std::mem::take(&mut summary.blobs) {
            let child = stats.summarise();
            summary.blanks += child.blanks;
            summary.code += child.code;
            summary.comments += child.comments;
        }
        summary
    }
}

impl AddAssign for CodeStats {
    fn add_assign(&mut self, rhs: Self) {
        self.blanks += rhs.blanks;
        self.code += rhs.code;
        self.comments += rhs.comments;
        for (language, stats) in rhs.blobs {
            *self.blobs.entry(language).or_default() += stats;
        }
    }
}

impl<'a> AddAssign<&'a CodeStats> for CodeStats {
    fn add_assign(&mut self, rhs: &'a Self) {
        self.blanks += rhs.blanks;
        self.code += rhs.code;
        self.comments += rhs.comments;
        for (language, stats) in &rhs.blobs {
            *self.blobs.entry(*language).or_default() += stats;
        }
    }
}

/// Statistics about a single file.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Report {
    pub name: std::path::PathBuf,
    pub stats: CodeStats,
}

impl Report {
    pub fn new(name: std::path::PathBuf) -> Self {
        Report { name, stats: CodeStats::new() }
    }
}
