    }

    #[inline]
    pub fn parse_line_comment(&self, window: &[u8]) -> bool {
        if self.quote.is_some() || !self.stack.is_empty() {
            return false;
        }
        if let Some(comment) = self
            .shared
            .line_comments
            .iter()
            .find(|c| window.starts_with(c.as_bytes()))
        {
            trace!("Start {:?}", comment);
            true
        } else {
            false
        }
    }

    #[inline]
    pub fn parse_quote(&mut self, window: &[u8]) -> Option<usize> {
        if !self.stack.is_empty() {
            return None;
        }

        if let Some((start, end)) = self
            .shared
            .doc_quotes
            .iter()
            .find(|(s, _)| window.starts_with(s.as_bytes()))
        {
            trace!("Start Doc {:?}", start);
            self.quote = Some(end);
            self.quote_is_verbatim = false;
            self.quote_is_doc_quote = true;
            return Some(start.len());
        }

        if let Some((start, end)) = self
            .shared
            .verbatim_string_literals
            .iter()
            .find(|(s, _)| window.starts_with(s.as_bytes()))
        {
            trace!("Start verbatim {:?}", start);
            self.quote = Some(end);
            self.quote_is_verbatim = true;
            self.quote_is_doc_quote = false;
            return Some(start.len());
        }

        if let Some((start, end)) = self
            .shared
            .string_literals
            .iter()
            .find(|(s, _)| window.starts_with(s.as_bytes()))
        {
            trace!("Start {:?}", start);
            self.quote = Some(end);
            self.quote_is_verbatim = false;
            self.quote_is_doc_quote = false;
            return Some(start.len());
        }

        None
    }

    #[inline]
    pub fn parse_end_of_quote(&mut self, window: &[u8]) -> Option<usize> {
        let quote = self.quote?;
        if window.starts_with(quote.as_bytes()) {
            trace!("End {:?}", quote);
            self.quote = None;
            self.quote_is_verbatim = false;
            self.quote_is_doc_quote = false;
            Some(quote.len())
        } else if !self.quote_is_verbatim && window.starts_with(br"\") {
            // Escaped character; skip it.
            Some(2)
        } else {
            None
        }
    }

    #[inline]
    pub fn parse_multi_line_comment(&mut self, window: &[u8]) -> Option<usize> {
        if self.quote.is_some() {
            return None;
        }

        let iter = self
            .shared
            .multi_line_comments
            .iter()
            .chain(self.shared.nested_comments.iter());
        for &(start, end) in iter {
            if window.starts_with(start.as_bytes()) {
                if self.stack.is_empty()
                    || self.shared.allows_nested
                    || self.shared.nested_comments.contains(&(start, end))
                {
                    self.stack.push(end);
                    if self.shared.allows_nested {
                        trace!("Start nested {:?}", start);
                    } else {
                        trace!("Start {:?}", start);
                    }
                }
                return Some(start.len());
            }
        }
        None
    }

    #[inline]
    pub fn parse_end_of_multi_line(&mut self, window: &[u8]) -> Option<usize> {
        if self
            .stack
            .last()
            .map_or(false, |l| window.starts_with(l.as_bytes()))
        {
            let last = self.stack.pop().unwrap();
            if self.stack.is_empty() {
                trace!("End {:?}", last);
            } else {
                trace!("End {:?}. Still in comments.", last);
            }
            Some(last.len())
        } else {
            None
        }
    }
}

/// Parse a whole slice of text with the given language.
pub fn parse_from_slice(language: LanguageType, text: &[u8], config: &Config) -> CodeStats {
    if language.is_jupyter() {
        return crate::jupyter::parse_jupyter(text, config).unwrap_or_default();
    }

    let syntax = SyntaxCounter::new(language);

    let split = syntax
        .shared
        .important_syntax
        .find(text)
        .and_then(|m| text[..=m.start()].iter().rposition(|&c| c == b'\n'));

    if let Some(end) = split {
        let (skippable_text, rest) = text.split_at(end + 1);
        trace!(
            "Using Simple Parse on {:?}",
            String::from_utf8_lossy(skippable_text)
        );
        let is_fortran = syntax.shared.is_fortran;
        let is_literate = syntax.shared.is_literate;
        let comments = syntax.shared.line_comments;

        let (blanks, code, comment_count) = simple_parse(skippable_text, is_fortran, is_literate, comments);
        let mut stats = parse_lines(language, config, rest, CodeStats::new(), syntax);
        stats.blanks += blanks;
        stats.code += code;
        stats.comments += comment_count;
        stats
    } else {
        parse_lines(language, config, text, CodeStats::new(), syntax)
    }
}

fn simple_parse(
    text: &[u8],
    is_fortran: bool,
    is_literate: bool,
    comments: &[&str],
) -> (usize, usize, usize) {
    let mut blanks = 0;
    let mut code = 0;
    let mut comment_count = 0;
    for line in LineIter::new(text) {
        let line = if is_fortran { line } else { line.trim() };
        if line.trim().is_empty() {
            blanks += 1;
        } else if is_literate || comments.iter().any(|c| line.starts_with(c.as_bytes())) {
            comment_count += 1;
        } else {
            code += 1;
        }
    }
    (blanks, code, comment_count)
}

/// Iterates over lines (without the terminating newline).
struct LineIter<'a> {
    text: &'a [u8],
    pos: usize,
}

impl<'a> LineIter<'a> {
    fn new(text: &'a [u8]) -> Self {
        LineIter { text, pos: 0 }
    }
}

impl<'a> Iterator for LineIter<'a> {
    type Item = &'a [u8];
    fn next(&mut self) -> Option<&'a [u8]> {
        if self.pos >= self.text.len() {
            return None;
        }
        let rest = &self.text[self.pos..];
        match memchr::memchr(b'\n', rest) {
            Some(p) => {
                self.pos += p + 1;
                Some(&rest[..p])
            }
            None => {
                self.pos = self.text.len();
                Some(rest)
            }
        }
    }
}

pub fn parse_lines(
    _language: LanguageType,
    config: &Config,
    lines: &[u8],
    mut stats: CodeStats,
    mut syntax: SyntaxCounter,
) -> CodeStats {
    let mut stepper = LineStep::new(b'\n', 0, lines.len());

    while let Some((start, end)) = stepper.next(lines) {
        let line = &lines[start..end];
        // FORTRAN has a rule where it only counts as a comment if it's the
        // first character in the column, so removing starting whitespace
        // could cause a miscount.
        let line = if syntax.shared.is_fortran { line } else { line.trim() };
        trace!("{}", String::from_utf8_lossy(line));

        if syntax.try_perform_single_line_analysis(line, &mut stats) {
            continue;
        }

        let started_in_comments = !syntax.stack.is_empty()
            || (config.treat_doc_strings_as_comments == Some(true)
                && syntax.quote.is_some()
                && syntax.quote_is_doc_quote);

        let ended_with_comments = match syntax.perform_multi_line_analysis(lines, start, end, config) {
            AnalysisReport::Normal(end) => end,
            AnalysisReport::ChildLanguage(FileContext {
                language,
                end,
                stats: blob,
                parent_code,
                parent_comments,
            }) => {
                stats.code += parent_code;
                stats.comments += parent_comments;
                *stats.blobs.entry(language).or_default() += blob;
                stepper = LineStep::new(b'\n', end, lines.len());
                continue;
            }
        };

        trace!("{}", String::from_utf8_lossy(line));

        if syntax.line_is_comment(line, config, ended_with_comments, started_in_comments) {
            stats.comments += 1;
            trace!("Comment No.{}", stats.comments);
            trace!("Was the Comment stack empty?: {}", !started_in_comments);
        } else {
            stats.code += 1;
            trace!("Code No.{}", stats.code);
        }
    }

    stats
}
