//! Small helpers for working with byte slices.

#[inline]
pub fn is_whitespace(b: u8) -> bool {
    b == b' ' || (b'\t'..=b'\r').contains(&b)
}

/// Whitespace that is not a newline.
#[inline]
pub fn is_inline_whitespace(b: u8) -> bool {
    b != b'\n' && is_whitespace(b)
}

pub trait SliceExt {
    fn trim(&self) -> &Self;
    fn trim_start(&self) -> &Self;
    fn trim_end(&self) -> &Self;
    fn trim_inline_start(&self) -> &Self;
    fn trim_inline_end(&self) -> &Self;
}

impl SliceExt for [u8] {
    fn trim(&self) -> &[u8] {
        self.trim_start().trim_end()
    }

    fn trim_start(&self) -> &[u8] {
        let mut i = 0;
        while i < self.len() && is_whitespace(self[i]) {
            i += 1;
        }
        &self[i..]
    }

    fn trim_end(&self) -> &[u8] {
        let mut end = self.len();
        while end > 0 && is_whitespace(self[end - 1]) {
            end -= 1;
        }
        &self[..end]
    }

    fn trim_inline_start(&self) -> &[u8] {
        let mut i = 0;
        while i < self.len() && is_inline_whitespace(self[i]) {
            i += 1;
        }
        &self[i..]
    }

    fn trim_inline_end(&self) -> &[u8] {
        let mut end = self.len();
        while end > 0 && is_inline_whitespace(self[end - 1]) {
            end -= 1;
        }
        &self[..end]
    }
}

/// Steps through a byte buffer one line at a time. The returned ranges
/// include the terminating newline (if any).
pub struct LineStep {
    byte: u8,
    start: usize,
    end: usize,
}

impl LineStep {
    pub fn new(byte: u8, start: usize, end: usize) -> Self {
        LineStep { byte, start, end }
    }

    pub fn next(&mut self, stream: &[u8]) -> Option<(usize, usize)> {
        if self.start >= self.end {
            return None;
        }
        let slice = &stream[self.start..self.end];
        let line_end = match memchr::memchr(self.byte, slice) {
            Some(pos) => self.start + pos + 1,
            None => self.end,
        };
        let range = (self.start, line_end);
        self.start = line_end;
        Some(range)
    }
}
