static START_TEMPLATE: Lazy<Regex> =
    Lazy::new(|| Regex::new(r#"^<template(?:.*lang="(.*)")?.*?>"#).unwrap());
static STARTING_MARKDOWN_REGEX: Lazy<Regex> = Lazy::new(|| Regex::new(r"^```(\S+)\s").unwrap());
static ENDING_MARKDOWN_REGEX: Lazy<Regex> = Lazy::new(|| Regex::new(r"```\s?").unwrap());
static LF_TARGET_REGEX: Lazy<Regex> = Lazy::new(|| Regex::new(r"target\s+(\w+)").unwrap());

pub fn parse_context(
    syntax: &mut SyntaxCounter,
    lines: &[u8],
    start: usize,
    end: usize,
    config: &Config,
) -> Option<FileContext> {
    let language = syntax.shared.language;
    if language.is_markdown_like() {
        markdown_context(lines, start, config)
    } else if language.is_html_like() {
        html_context(lines, start, end, config)
    } else if language.is_rust() {
        rust_context(lines, start, config)
    } else if language.is_lingua_franca() {
        lingua_franca_context(syntax, lines, start, config)
    } else {
        None
    }
}

fn find(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() {
        return Some(0);
    }
    memchr::memmem::find(haystack, needle)
}

/// Shared handling of a block following an opening token at `p` (the end of
/// the opening tag). Returns the slice to parse, the end of the block and
/// whether the block was accepted.
fn block_after_tag(lines: &[u8], mut p: usize, end_of_code: usize) -> Option<(usize, usize)> {
    while p < end_of_code && is_inline_whitespace(lines[p]) {
        p += 1;
    }
    let content = &lines[p..end_of_code];
    if content.trim().is_empty() {
        return None;
    }
    let start_of_code = if p + 1 < end_of_code { p + 1 } else { p };
    let block = lines[start_of_code..end_of_code].trim_inline_end();
    Some((start_of_code, start_of_code + block.len()))
}

fn html_context(lines: &[u8], start: usize, end: usize, config: &Config) -> Option<FileContext> {
    // The current line, without its terminating newline.
    let mut line_end = end;
    if line_end > start && lines[line_end - 1] == b'\n' {
        line_end -= 1;
    }
    let line = &lines[start..line_end];

    let (opening_end, closing_tag, language) = if let Some(caps) = START_SCRIPT.captures(line) {
        let language = caps
            .get(1)
            .and_then(|m| {
                let mime = String::from_utf8_lossy(m.as_bytes()).into_owned();
                let l = LanguageType::from_mime(&mime);
                if l.is_none() {
                    trace!("Unknown MIME: {}", mime);
                }
                l
            })
            .unwrap_or(LanguageType::JavaScript);
        (caps.get(0).unwrap().end(), &b"</script>"[..], language)
    } else if let Some(caps) = START_STYLE.captures(line) {
        let language = caps
            .get(1)
            .and_then(|m| LanguageType::from_str_name(&String::from_utf8_lossy(m.as_bytes())))
            .unwrap_or(LanguageType::Css);
        (caps.get(0).unwrap().end(), &b"</style>"[..], language)
    } else if let Some(caps) = START_TEMPLATE.captures(line) {
        let language = caps
            .get(1)
            .and_then(|m| LanguageType::from_str_name(&String::from_utf8_lossy(m.as_bytes())))
            .unwrap_or(LanguageType::Html);
        (caps.get(0).unwrap().end(), &b"</template>"[..], language)
    } else {
        return None;
    };

    let mut p = start + opening_end;
    while p < lines.len() && is_inline_whitespace(lines[p]) {
        p += 1;
    }
    let end_of_code = p + find(&lines[p..], closing_tag)?;
    let (block_start, block_end) = block_after_tag(lines, p, end_of_code)?;
    let stats = parse_from_slice(language, &lines[block_start..block_end], config);

    Some(FileContext {
        language,
        end: end_of_code,
        stats,
        parent_code: 1,
        parent_comments: 0,
    })
}

fn markdown_context(lines: &[u8], start: usize, config: &Config) -> Option<FileContext> {
    let window = &lines[start..];
    let caps = STARTING_MARKDOWN_REGEX.captures(window)?;
    let opening = caps.get(0).unwrap();
    let ident = caps.get(1).unwrap();
    let rest = &window[opening.end()..];
    let closing = ENDING_MARKDOWN_REGEX.find(rest);
    if let Some(m) = &closing {
        trace!("{:?}", String::from_utf8_lossy(m.as_bytes()));
    }
    let language = LanguageType::from_str_name(&String::from_utf8_lossy(ident.as_bytes()))?;
    let (block, end, parent_comments) = match closing {
        Some(m) => (&rest[..m.start()], start + opening.end() + m.end(), 2),
        None => (rest, lines.len(), 1),
    };
    trace!("{} BLOCK: {:?}", language.name(), String::from_utf8_lossy(block));
    let stats = parse_from_slice(language, block.trim(), config);
    Some(FileContext {
        language,
        end,
        stats,
        parent_code: 0,
        parent_comments,
    })
}

fn rust_context(lines: &[u8], start: usize, config: &Config) -> Option<FileContext> {
    let window = &lines[start..];
    let trimmed = window.trim_start();
    let prefix: &[u8] = if trimmed.starts_with(b"///") {
        b"///"
    } else if trimmed.starts_with(b"//!") {
        b"//!"
    } else {
        return None;
    };
    let pos = start + (window.len() - trimmed.len());
    let mut block: Vec<u8> = Vec::new();
    let mut end = pos;
    let mut stepper = LineStep::new(b'\n', pos, lines.len());
    while let Some((ls, le)) = stepper.next(lines) {
        let line = &lines[ls..le];
        trace!("{}", String::from_utf8_lossy(line));
        let tl = line.trim_start();
        if tl.starts_with(prefix) {
            block.extend_from_slice(&tl[prefix.len()..]);
            end = le;
        } else if line.trim().is_empty() {
            continue;
        } else {
            break;
        }
    }
    trace!("Markdown found: {:?}", String::from_utf8_lossy(&block));
    let stats = parse_from_slice(LanguageType::Markdown, block.trim(), config);
    Some(FileContext {
        language: LanguageType::Markdown,
        end,
        stats,
        parent_code: 0,
        parent_comments: 0,
    })
}

fn lingua_franca_context(
    syntax: &mut SyntaxCounter,
    lines: &[u8],
    start: usize,
    config: &Config,
) -> Option<FileContext> {
    let window = &lines[start..];
    if !window.starts_with(b"{=") {
        return None;
    }
    let language = match syntax.lf_embedded_language {
        Some(l) => l,
        None => {
            let l = LF_TARGET_REGEX
                .captures(lines)
                .and_then(|c| c.get(1))
                .and_then(|m| match m.as_bytes() {
                    b"C" | b"CCpp" => Some(LanguageType::C),
                    b"Cpp" => Some(LanguageType::Cpp),
                    b"Python" => Some(LanguageType::Python),
                    b"Rust" => Some(LanguageType::Rust),
                    b"TypeScript" => Some(LanguageType::TypeScript),
                    _ => None,
                })
                .unwrap_or(LanguageType::LinguaFranca);
            syntax.lf_embedded_language = Some(l);
            l
        }
    };
    let p = start + 2;
    let end_of_code = match find(&lines[p..], b"=}") {
        Some(pos) => p + pos,
        None => lines.len(),
    };
    trace!("LF block: {:?}", String::from_utf8_lossy(&lines[p..end_of_code]));
    let (block_start, block_end) = block_after_tag(lines, p, end_of_code)?;
    let stats = parse_from_slice(language, &lines[block_start..block_end], config);
    trace!("-> stats: {:?}", stats);
    Some(FileContext {
        language,
        end: end_of_code,
        stats,
        parent_code: 1,
        parent_comments: 0,
    })
}
