//! Configuration, read from the command line and `tokei.toml`/`.tokeirc`.

use std::path::{Path, PathBuf};

use crate::language_type::LanguageType;
use crate::sort::Sort;

#[derive(Debug, Default, Clone)]
pub struct Config {
    pub columns: Option<usize>,
    pub hidden: Option<bool>,
    pub no_ignore: Option<bool>,
    pub no_ignore_parent: Option<bool>,
    pub no_ignore_dot: Option<bool>,
    pub no_ignore_vcs: Option<bool>,
    pub treat_doc_strings_as_comments: Option<bool>,
    pub sort: Option<Sort>,
    pub types: Option<Vec<LanguageType>>,
}

impl Config {
    /// Reads a configuration file from `dir`, trying `tokei.toml` then
    /// `.tokeirc`. Returns `None` if no valid file was found.
    fn from_dir(dir: &Path) -> Option<Config> {
        for name in ["tokei.toml", ".tokeirc"] {
            let path = dir.join(name);
            if let Ok(contents) = std::fs::read_to_string(&path) {
                if let Some(config) = Config::parse_toml(&contents) {
                    return Some(config);
                }
            }
        }
        None
    }

    /// Parses a configuration file. Any error results in `None` (the whole
    /// file is ignored).
    pub fn parse_toml(contents: &str) -> Option<Config> {
        let table: toml::Table = contents.parse().ok()?;
        let mut config = Config::default();
        for (key, value) in &table {
            match key.as_str() {
                "columns" => config.columns = Some(as_usize(value)?),
                "hidden" => config.hidden = Some(value.as_bool()?),
                "no_ignore" => config.no_ignore = Some(value.as_bool()?),
                "no_ignore_parent" => config.no_ignore_parent = Some(value.as_bool()?),
                "no_ignore_dot" => config.no_ignore_dot = Some(value.as_bool()?),
                "no_ignore_vcs" => config.no_ignore_vcs = Some(value.as_bool()?),
                "treat_doc_strings_as_comments" => {
                    config.treat_doc_strings_as_comments = Some(value.as_bool()?)
                }
                "sort" => {
                    let s = value.as_str()?;
                    config.sort = Some(Sort::from_str_case_insensitive(s)?);
                }
                "types" => {
                    let arr = value.as_array()?;
                    let mut types = Vec::new();
                    for v in arr {
                        let s = v.as_str()?;
                        types.push(LanguageType::deserialize_name(s)?);
                    }
                    config.types = Some(types);
                }
                _ => {}
            }
        }
        Some(config)
    }

    /// Loads the configuration from the config directory, the home directory
    /// and the current directory (later ones taking precedence).
    pub fn from_config_files() -> Config {
        let conf_dir = crate::utils::fs::config_dir().and_then(|d| Config::from_dir(&d));
        let home_dir = crate::utils::fs::home_dir().and_then(|d| Config::from_dir(&d));
        let current_dir = std::env::current_dir()
            .ok()
            .and_then(|d: PathBuf| Config::from_dir(&d));

        let mut config = Config::default();
        for c in [conf_dir, home_dir, current_dir].into_iter().flatten() {
            config = config.merge(c);
        }
        config
    }

    /// Merges `other` into `self`, with `other` taking precedence.
    fn merge(self, other: Config) -> Config {
        Config {
            columns: other.columns.or(self.columns),
            hidden: other.hidden.or(self.hidden),
            no_ignore: other.no_ignore.or(self.no_ignore),
            no_ignore_parent: other.no_ignore_parent.or(self.no_ignore_parent),
            no_ignore_dot: other.no_ignore_dot.or(self.no_ignore_dot),
            no_ignore_vcs: other.no_ignore_vcs.or(self.no_ignore_vcs),
            treat_doc_strings_as_comments: other
                .treat_doc_strings_as_comments
                .or(self.treat_doc_strings_as_comments),
            sort: other.sort.or(self.sort),
            types: other.types.or(self.types),
        }
    }
}

fn as_usize(value: &toml::Value) -> Option<usize> {
    let i = value.as_integer()?;
    if i < 0 {
        None
    } else {
        Some(i as usize)
    }
}
