#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Sort {
    Blanks,
    Comments,
    Code,
    Files,
    Lines,
}

impl Sort {
    pub fn from_str_case_insensitive(s: &str) -> Option<Sort> {
        match s.to_lowercase().as_str() {
            "blanks" => Some(Sort::Blanks),
            "comments" => Some(Sort::Comments),
