//! Aggregated statistics for a single language and for all languages.

use std::collections::BTreeMap;

use crate::language_type::LanguageType;
use crate::sort::Sort;
use crate::stats::{CodeStats, Report};

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Language {
    pub blanks: usize,
    pub code: usize,
    pub comments: usize,
    pub reports: Vec<Report>,
    pub children: BTreeMap<LanguageType, Vec<Report>>,
    pub inaccurate: bool,
}

impl Language {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_report(&mut self, report: Report) {
        for (language, stats) in &report.stats.blobs {
            let mut child_report = Report::new(report.name.clone());
            child_report.stats = stats.clone();
            self.children
                .entry(*language)
                .or_default()
                .push(child_report);
        }
        self.blanks += report.stats.blanks;
        self.code += report.stats.code;
        self.comments += report.stats.comments;
        self.reports.push(report);
    }

    pub fn mark_inaccurate(&mut self) {
        self.inaccurate = true;
    }

    pub fn lines(&self) -> usize {
        self.blanks + self.code + self.comments
    }

    pub fn is_empty(&self) -> bool {
        self.code == 0 && self.comments == 0 && self.blanks == 0 && self.children.is_empty()
    }

    /// A copy of this language where all the children have been folded into
    /// the top level numbers.
    pub fn summarise(&self) -> Language {
        let mut summary = self.clone();
        for reports in self.children.values() {
            for report in reports {
                let stats = report.stats.summarise();
                summary.blanks += stats.blanks;
                summary.code += stats.code;
                summary.comments += stats.comments;
            }
        }
        summary
    }

    /// Summed statistics of the reports of a child language (including their
    /// own nested blobs).
    pub fn child_stats(reports: &[Report]) -> CodeStats {
        let mut stats = CodeStats::new();
        for report in reports {
            let s = report.stats.summarise();
            stats.blanks += s.blanks;
            stats.code += s.code;
            stats.comments += s.comments;
        }
        stats
    }

    pub fn sort_by(&mut self, category: Sort) {
        match category {
            Sort::Blanks => self
                .reports
                .sort_by(|a, b| b.stats.blanks.cmp(&a.stats.blanks)),
            Sort::Comments => self
                .reports
                .sort_by(|a, b| b.stats.comments.cmp(&a.stats.comments)),
            Sort::Code => self
                .reports
                .sort_by(|a, b| b.stats.code.cmp(&a.stats.code)),
            Sort::Files => {}
            Sort::Lines => self
                .reports
                .sort_by(|a, b| b.stats.lines().cmp(&a.stats.lines())),
        }
    }

    pub fn sort_reports_by_name(&mut self) {
        self.reports.sort_by(|a, b| a.name.cmp(&b.name));
        for reports in self.children.values_mut() {
            reports.sort_by(|a, b| a.name.cmp(&b.name));
        }
    }
}

impl std::ops::AddAssign for Language {
    fn add_assign(&mut self, rhs: Self) {
        self.blanks += rhs.blanks;
        self.code += rhs.code;
        self.comments += rhs.comments;
        self.reports.extend(rhs.reports);
        for (language, reports) in rhs.children {
            self.children.entry(language).or_default().extend(reports);
        }
        self.inaccurate |= rhs.inaccurate;
    }
}

pub type Languages = BTreeMap<LanguageType, Language>;

/// Computes the `Total` pseudo-language.
pub fn total(languages: &Languages) -> Language {
    let mut total = Language::new();
    for (language_type, language) in languages {
        let summary = language.summarise();
        total.blanks += summary.blanks;
        total.code += summary.code;
        total.comments += summary.comments;
        total.inaccurate |= language.inaccurate;
        if !language.reports.is_empty() {
            total
                .children
                .entry(*language_type)
                .or_default()
                .extend(language.reports.iter().cloned());
        }
    }
    total
}
