EXTRA = ['💭🔜', '🔚💭', '📗', '📘', '🔤', '❌', '⍝', '⊣', '⊢', '#region', '#endregion', 'NB.', 'Note', 'note', 'comment', 'Comment', 'COMMENT', 'rem', 'REM', 'Rem', 'C', 'c', 'd', 'D', '´', '¨', '§', '¶', '†', '‡', '•', '…', '‹', '›', '«', '»', '¡', '¿', '¬', '¦', '°', '·', '×', '÷', '→', '←', '⇒', '∎', '□', '■', '◊', '♯', '♭', '♮', '⌈', '⌉', '⌊', '⌋', '〈', '〉', '《', '》', '「', '」', '『', '』', '【', '】', '〔', '〕', '。', '、', '，', '；', '：', '？', '！', '（', '）', '｛', '｝', '［', '］', '「「', '」」', '批曰。', '疏曰。', '注曰。', '論曰。', '疏', '批', '注', '書之', '曰', '云', '恆', '吾有', '昔之', '今', '🍇', '🍉', '🔥', '🚀', '💬', '🗨', '📝', '✏', '🤔', '👴']
CANDS += EXTRA

def probe_lang(res, workdir):
    name = res['name']; fname = res['file']; key = res['json_key']
    known = set()
    for tok, info in res['tokens'].items():
        for kind, t in info['cls']:
            known.add(t)
    found = {}
    for tok in CANDS:
        content = 'zq0\n' + tok + ' zq1\nzq2\n'
        msgs, stats = run_probe(name, fname, content, workdir)
        st = stats[key] if (stats and key in stats) else None
        if st is None: continue
        important = any(m.startswith('Using Simple Parse') for m in msgs)
        ev = [m for m in msgs if m.startswith('Start') or m.startswith('End')]
        comment_l2 = False
        # determine whether line2 is comment: compare with baseline
        base = res['baseline']
        cur = (st['code'], st['comments'], st['blanks'])
        if cur != tuple(base) or important or ev:
            found[tok] = {'stats': cur, 'important': important, 'events': ev[:3]}
    return {'name': name, 'found': found, 'known': sorted(known)}

if __name__ == '__main__':
    r1 = json.load(open('/tmp/probe/probe1_results.json'))
    base = '/tmp/probe/work3'; os.makedirs(base, exist_ok=True)
    results = {}
    def work(item):
        i, (name, res) = item
        wd = os.path.join(base, f'w{i}'); os.makedirs(wd, exist_ok=True)
        try:
            return probe_lang(res, wd)
        except Exception as ex:
            import traceback; traceback.print_exc()
            return {'name': name, 'error': str(ex)}
    items = list(enumerate(r1.items()))
    with ThreadPoolExecutor(max_workers=56) as ex:
        for r in ex.map(work, items):
            results[r['name']] = r
            print('done', r['name'], file=sys.stderr)
            json.dump(results, open('/tmp/probe/probe3_results.json', 'w'), indent=1, ensure_ascii=False)
