//! The set of supported languages and how files are mapped to them.

use std::collections::HashMap;
use std::fmt;
use std::path::Path;

use once_cell::sync::Lazy;

pub use crate::language_data::{LangDef, LanguageType, ALL_LANGUAGES, DEFS, LANGUAGE_COUNT};

static EXTENSION_MAP: Lazy<HashMap<&'static str, LanguageType>> = Lazy::new(|| {
    let mut map = HashMap::new();
    for &language in ALL_LANGUAGES.iter() {
        for ext in language.def().extensions {
            map.entry(*ext).or_insert(language);
        }
    }
    map
});

static FILENAME_MAP: Lazy<HashMap<&'static str, LanguageType>> = Lazy::new(|| {
    let mut map = HashMap::new();
    for &language in ALL_LANGUAGES.iter() {
        for name in language.def().filenames {
            map.entry(*name).or_insert(language);
        }
    }
    map
});

static NAME_MAP: Lazy<HashMap<String, LanguageType>> = Lazy::new(|| {
    let mut map = HashMap::new();
    for &language in ALL_LANGUAGES.iter() {
        map.entry(language.name().to_lowercase()).or_insert(language);
    }
    map
});

impl LanguageType {
    #[inline]
    pub fn def(self) -> &'static LangDef {
        &DEFS[self as usize]
    }

    /// The human readable name of the language.
    pub fn name(self) -> &'static str {
        self.def().name
    }

    pub fn variant_name(self) -> &'static str {
        self.def().variant
    }

    pub fn list() -> &'static [LanguageType] {
        &ALL_LANGUAGES
    }

    pub fn is_literate(self) -> bool {
        self.def().literate
    }

    pub fn is_fortran(self) -> bool {
        matches!(self, LanguageType::FortranLegacy | LanguageType::FortranModern)
    }

    pub fn is_html_like(self) -> bool {
        matches!(
            self,
            LanguageType::Html
                | LanguageType::Vue
                | LanguageType::Svelte
                | LanguageType::RubyHtml
                | LanguageType::GlimmerJs
                | LanguageType::GlimmerTs
        )
    }

    pub fn is_markdown_like(self) -> bool {
        matches!(
            self,
            LanguageType::Markdown | LanguageType::UnrealDeveloperMarkdown
        )
    }

    pub fn is_rust(self) -> bool {
        self == LanguageType::Rust
    }

    pub fn is_lingua_franca(self) -> bool {
        self == LanguageType::LinguaFranca
    }

    pub fn is_jupyter(self) -> bool {
        self == LanguageType::Jupyter
    }

    /// Case insensitive lookup by the human readable name.
    pub fn from_str_name(s: &str) -> Option<LanguageType> {
        NAME_MAP.get(&s.to_lowercase()).copied()
    }

    /// Lookup used when deserializing: the exact human readable name or the
    /// exact variant identifier.
    pub fn deserialize_name(s: &str) -> Option<LanguageType> {
        ALL_LANGUAGES
            .iter()
            .copied()
            .find(|l| l.name() == s || l.variant_name() == s)
    }

    pub fn from_file_extension(extension: &str) -> Option<LanguageType> {
        EXTENSION_MAP.get(extension).copied()
    }

    pub fn from_mime(mime: &str) -> Option<LanguageType> {
        ALL_LANGUAGES
            .iter()
            .copied()
            .find(|l| l.def().mime.contains(&mime))
    }

    /// Reads the first line of the file and tries to match it against the
    /// known shebangs.
    pub fn from_shebang(path: &Path) -> Option<LanguageType> {
        use std::io::{BufRead, BufReader};
        let file = std::fs::File::open(path).ok()?;
        let mut reader = BufReader::new(file);
        let mut line = String::new();
        reader.read_line(&mut line).ok()?;
        let mut words = line.split_whitespace();
        let first = words.next()?;
        if !first.starts_with("#!") {
            return None;
        }
        if first == "#!/usr/bin/env" {
            let interpreter = words.next()?;
            ALL_LANGUAGES
                .iter()
                .copied()
                .find(|l| l.def().env.iter().any(|e| interpreter.starts_with(e)))
        } else {
            ALL_LANGUAGES
                .iter()
                .copied()
                .find(|l| l.def().shebangs.contains(&first))
        }
    }

    pub fn from_path(path: &Path) -> Option<LanguageType> {
        let filename = path
            .file_name()
            .and_then(|f| f.to_str())
            .map(|f| f.to_lowercase());
        if let Some(filename) = &filename {
            if let Some(&language) = FILENAME_MAP.get(filename.as_str()) {
                return Some(language);
            }
        }
        match path.extension().and_then(|e| e.to_str()) {
            Some(extension) => {
                let extension = extension.to_lowercase();
                let language = Self::from_file_extension(&extension);
                if language.is_none() {
                    log::warn!("Unknown extension: {}", extension);
                }
                language
            }
            None => Self::from_shebang(path),
        }
    }
}

impl fmt::Display for LanguageType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.name())
    }
}
EOF
echo ok"}

