}

/// Walks all the given paths and adds the statistics of every recognised
/// file to `languages`.
pub fn get_all_files<A: AsRef<str>>(
    paths: &[A],
    ignored_directories: &[A],
    languages: &mut Languages,
    config: &Config,
    for_each: Option<&(dyn Fn(LanguageType, &Report) + Sync)>,
) {
    let (tx, rx) = crossbeam_channel::unbounded::<DirEntry>();

    let mut paths = paths.iter();
    let mut walker = WalkBuilder::new(paths.next().expect("at least one path").as_ref());
    for path in paths {
        walker.add(path.as_ref());
    }

    if !ignored_directories.is_empty() {
        let mut overrides = OverrideBuilder::new(".");
        for ignored in ignored_directories {
            if let Err(error) = overrides.add(&format!("!{}", ignored.as_ref())) {
                log::error!("{}", error);
            }
        }
        walker.overrides(overrides.build().expect("Excludes provided were invalid"));
    }

    let no_ignore = config.no_ignore.unwrap_or(false);
    let no_ignore_dot = no_ignore || config.no_ignore_dot.unwrap_or(false);
    let no_ignore_vcs = no_ignore || config.no_ignore_vcs.unwrap_or(false);
    let no_ignore_parent = no_ignore || config.no_ignore_parent.unwrap_or(false);

    walker
        .hidden(!config.hidden.unwrap_or(false))
        .ignore(!no_ignore_dot)
        .git_global(!no_ignore_vcs)
        .git_ignore(!no_ignore_vcs)
        .git_exclude(!no_ignore_vcs)
        .parents(!no_ignore_parent);

    if !no_ignore_dot {
        walker.add_custom_ignore_filename(".tokeignore");
    }

    walker.build_parallel().run(move || {
        let tx = tx.clone();
        Box::new(move |entry| {
            let entry = match entry {
                Ok(entry) => entry,
                Err(error) => {
                    log::error!("{}", error);
                    return WalkState::Continue;
                }
            };
            if entry.file_type().map_or(false, |ft| ft.is_file()) {
                let _ = tx.send(entry);
            }
            WalkState::Continue
        })
    });

    let entries: Vec<DirEntry> = rx.into_iter().collect();
    let types = config.types.clone();

    let results: Vec<(LanguageType, PathBuf, Result<CodeStats, std::io::Error>)> = entries
        .into_par_iter()
        .filter_map(|entry| {
            let path = entry.into_path();
            let language = LanguageType::from_path(&path)?;
            if let Some(types) = &types {
                if !types.contains(&language) {
                    return None;
                }
            }
            Some((language, path))
        })
        .map(|(language, path)| {
            let result = parse_file(language, &path, config);
            (language, path, result)
        })
        .collect();

    for (language_type, path, result) in results {
        let entry = languages.entry(language_type).or_insert_with(Language::new);
        match result {
            Ok(stats) => {
                let mut report = Report::new(path);
                report.stats = stats;
                if let Some(f) = for_each {
                    f(language_type, &report);
                }
                entry.add_report(report);
            }
            Err(error) => {
                entry.mark_inaccurate();
                log::error!("Error reading {}:\n{}", path.display(), error);
            }
        }
    }
}
