//! Terminal output.

use std::io::{self, Write};

use crate::language::{total, Language, Languages};
use crate::language_type::LanguageType;
use crate::sort::Sort;
use crate::stats::Report;

pub const FALLBACK_ROW_LEN: usize = 81;
const NO_LANG_HEADER_ROW_LEN: usize = 67;
const NO_LANG_ROW_LEN: usize = 61;
const NO_LANG_ROW_LEN_NO_SPACES: usize = 63;
const IGNORE_SIGN: &str = "(!)";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NumberFormatStyle {
    Commas,
    Dots,
    Plain,
    Underscores,
}

impl NumberFormatStyle {
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "commas" => Some(Self::Commas),
            "dots" => Some(Self::Dots),
            "plain" => Some(Self::Plain),
            "underscores" => Some(Self::Underscores),
            _ => None,
        }
    }

    fn separator(self) -> Option<char> {
        match self {
            Self::Commas => Some(','),
            Self::Dots => Some('.'),
            Self::Plain => None,
            Self::Underscores => Some('_'),
        }
    }

    pub fn format(self, n: usize) -> String {
        let digits = n.to_string();
        match self.separator() {
            None => digits,
            Some(sep) => {
                let bytes = digits.as_bytes();
                let mut out = String::with_capacity(digits.len() + digits.len() / 3);
                for (i, b) in bytes.iter().enumerate() {
                    if i > 0 && (bytes.len() - i) % 3 == 0 {
                        out.push(sep);
                    }
                    out.push(*b as char);
                }
                out
            }
        }
    }
}

pub struct Printer<W> {
    writer: W,
    columns: usize,
    path_length: usize,
    row: String,
    subrow: String,
    list_files: bool,
    number_format: NumberFormatStyle,
}

impl<W: Write> Printer<W> {
    pub fn new(columns: usize, list_files: bool, writer: W, number_format: NumberFormatStyle) -> Self {
        Self {
            columns,
            list_files,
            path_length: columns - NO_LANG_ROW_LEN,
            writer,
            row: "━".repeat(columns),
            subrow: "─".repeat(columns),
            number_format,
        }
    }

    pub fn print_header(&mut self) -> io::Result<()> {
        self.print_row()?;
        writeln!(
            self.writer,
            " {:<6$} {:>12} {:>12} {:>12} {:>12} {:>12}",
            "Language",
            "Files",
            "Lines",
            "Code",
            "Comments",
            "Blanks",
            self.columns - NO_LANG_HEADER_ROW_LEN
        )?;
        self.print_row()
    }

    pub fn print_inaccuracy_warning(&mut self) -> io::Result<()> {
        writeln!(
            self.writer,
            "Note: results can be inaccurate for languages marked with '{}'",
            IGNORE_SIGN
        )
    }

    pub fn print_language(&mut self, language: &Language, name: &str) -> io::Result<()> {
        self.print_language_name(language.inaccurate, name, None)?;
        write!(self.writer, " ")?;
        writeln!(
            self.writer,
            "{:>6} {:>12} {:>12} {:>12} {:>12}",
            language.reports.len(),
            self.number_format.format(language.lines()),
            self.number_format.format(language.code),
            self.number_format.format(language.comments),
            self.number_format.format(language.blanks)
        )
    }

    fn print_language_total(&mut self, parent: &Language) -> io::Result<()> {
        for (language, reports) in &parent.children {
            let stats = Language::child_stats(reports);
            self.print_language_name(false, language.name(), Some("|- "))?;
            write!(self.writer, " ")?;
            writeln!(
                self.writer,
                "{:>6} {:>12} {:>12} {:>12} {:>12}",
                reports.len(),
                self.number_format.format(stats.lines()),
                self.number_format.format(stats.code),
                self.number_format.format(stats.comments),
                self.number_format.format(stats.blanks)
            )?;
        }
        let summary = parent.summarise();
        writeln!(
            self.writer,
            " {:<6$} {:>12} {:>12} {:>12} {:>12}",
            "(Total)",
            self.number_format.format(summary.lines()),
            self.number_format.format(summary.code),
            self.number_format.format(summary.comments),
            self.number_format.format(summary.blanks),
            self.path_length
        )
    }

    pub fn print_language_name(
        &mut self,
        inaccurate: bool,
        name: &str,
        prefix: Option<&str>,
    ) -> io::Result<()> {
        let mut lang_section_len =
            self.columns - NO_LANG_ROW_LEN_NO_SPACES - prefix.map_or(0, str::len);
        if inaccurate {
            lang_section_len -= IGNORE_SIGN.len();
        }

        if let Some(prefix) = prefix {
            write!(self.writer, " {}", prefix)?;
        } else {
            write!(self.writer, " ")?;
        }

        // Truncate and replace the last char with a `|` if the name is too long.
        if lang_section_len < name.chars().count() {
            let truncated: String = name.chars().take(lang_section_len - 1).collect();
            write!(self.writer, "{}|", truncated)?;
        } else {
            write!(self.writer, "{:<1$}", name, lang_section_len)?;
        }

        if inaccurate {
            write!(self.writer, "{}", IGNORE_SIGN)?;
        }

        Ok(())
    }

    fn print_code_stats(
        &mut self,
        language_type: LanguageType,
        stats: &[Report],
    ) -> io::Result<()> {
        self.print_language_name(false, language_type.name(), Some("|- "))?;
        let mut code = 0;
        let mut comments = 0;
        let mut blanks = 0;
        for report in stats {
            let s = report.stats.summarise();
            code += s.code;
            comments += s.comments;
            blanks += s.blanks;
        }
        let lines = code + comments + blanks;
        if stats.is_empty() {
            Ok(())
        } else {
            writeln!(
                self.writer,
                " {:>6} {:>12} {:>12} {:>12} {:>12}",
                stats.len(),
                self.number_format.format(lines),
                self.number_format.format(code),
                self.number_format.format(comments),
                self.number_format.format(blanks),
            )
        }
    }

    fn print_language_in_print_total(&mut self, language: &Language) -> io::Result<()> {
        self.print_language_name(language.inaccurate, "Total", None)?;
        write!(self.writer, " ")?;
        let files: usize = language.children.values().map(Vec::len).sum::<usize>()
            + language.reports.len();
        writeln!(
            self.writer,
            "{:>6} {:>12} {:>12} {:>12} {:>12}",
            files,
            self.number_format.format(language.lines()),
            self.number_format.format(language.code),
            self.number_format.format(language.comments),
            self.number_format.format(language.blanks)
        )
    }

    pub fn print_results<'a, I>(
        &mut self,
        languages: I,
        compact: bool,
        is_sorted: bool,
    ) -> io::Result<()>
    where
        I: Iterator<Item = (&'a LanguageType, &'a Language)>,
    {
        let (a, b): (Vec<_>, Vec<_>) = languages
            .filter(|(_, v)| !v.is_empty())
            .partition(|(_, l)| compact || l.children.is_empty());
        let mut first = true;

        for languages in &[&a, &b] {
            for &(name, language) in languages.iter() {
                let has_children = !compact && !language.children.is_empty();
                if first {
                    first = false;
                } else if has_children || self.list_files {
                    self.print_subrow()?;
                }

                self.print_language(language, name.name())?;
                if has_children {
                    self.print_language_total(language)?;
                }

                if self.list_files {
                    self.print_subrow()?;
                    let mut reports: Vec<&Report> = language.reports.iter().collect();
                    if !is_sorted {
                        reports.sort_by(|a, b| a.name.cmp(&b.name));
                    }
                    if compact {
                        for report in &reports {
                            self.print_report_plain(report)?;
                        }
                    } else {
                        let (a, b): (Vec<&Report>, Vec<&Report>) =
                            reports.iter().partition(|r| r.stats.blobs.is_empty());
                        for reports in &[a, b] {
                            let mut first = true;
                            for report in reports {
                                if report.stats.blobs.is_empty() {
                                    self.print_report_plain(report)?;
                                } else {
                                    if first {
                                        first = false;
                                    } else {
                                        self.print_subrow()?;
                                    }
                                    self.print_report_with_blobs(report, *name)?;
                                }
                            }
                        }
                    }
                }
            }
        }

        Ok(())
    }

    fn print_report_plain(&mut self, report: &Report) -> io::Result<()> {
        let name = report.name.to_string_lossy();
        writeln!(
            self.writer,
            " {:<5$} {:>12} {:>12} {:>12} {:>12}",
            self.truncate_path(&name),
            report.stats.lines(),
            report.stats.code,
            report.stats.comments,
            report.stats.blanks,
            self.path_length
        )
    }

    fn truncate_path(&self, name: &str) -> String {
        let count = name.chars().count();
        if count > self.path_length {
            let keep = self.path_length - 1;
            let skip = count - keep;
            format!("|{}", name.chars().skip(skip).collect::<String>())
        } else {
            name.to_string()
        }
    }

    fn print_report_with_blobs(&mut self, report: &Report, parent: LanguageType) -> io::Result<()> {
        let name = report.name.to_string_lossy();
        writeln!(self.writer, " {}", self.truncate_path(&name))?;
        // The parent's own statistics, printed as a child row.
        self.print_language_name(false, parent.name(), Some("|- "))?;
        writeln!(
            self.writer,
            "{:>6} {:>12} {:>12} {:>12} {:>12}",
            "",
            report.stats.lines(),
            report.stats.code,
            report.stats.comments,
            report.stats.blanks,
        )?;
        for (language, stats) in &report.stats.blobs {
            let s = stats.summarise();
            self.print_language_name(false, language.name(), Some("|- "))?;
            writeln!(
                self.writer,
                "{:>6} {:>12} {:>12} {:>12} {:>12}",
                "",
                self.number_format.format(s.lines()),
                self.number_format.format(s.code),
                self.number_format.format(s.comments),
                self.number_format.format(s.blanks),
            )?;
        }
        writeln!(
            self.writer,
            " {:<5$} {:>12} {:>12} {:>12} {:>12}",
            self.truncate_path(&name),
            self.number_format.format(report.stats.lines()),
            self.number_format.format(report.stats.code),
            self.number_format.format(report.stats.comments),
            self.number_format.format(report.stats.blanks),
            self.path_length
        )
    }

    pub fn print_row(&mut self) -> io::Result<()> {
        writeln!(self.writer, "{}", self.row)
    }

    fn print_subrow(&mut self) -> io::Result<()> {
        writeln!(self.writer, "{}", self.subrow)
    }

    pub fn print_total(&mut self, languages: &Languages) -> io::Result<()> {
        let total = total(languages);
        self.print_row()?;
        self.print_language_in_print_total(&total)?;
        self.print_row()
    }
}

/// Prints the list of supported languages and their extensions.
pub fn print_supported_languages<W: Write>(mut writer: W) -> io::Result<()> {
    const WIDTH: usize = 72;
    let row = "━".repeat(WIDTH);
    writeln!(writer, "{}", row)?;
    writeln!(writer, "┃ {:<38}{:<31}┃", "Language", "Extensions")?;
    writeln!(writer, "┃{}┃", "━".repeat(WIDTH - 2))?;
    for language in LanguageType::list() {
        let def = language.def();
        let mut exts = if def.extensions_display.is_empty() {
            "<None>".to_string()
        } else {
            def.extensions_display.to_string()
        };
        if exts.chars().count() > 30 {
            exts = format!("{}...", exts.chars().take(27).collect::<String>());
        }
        writeln!(writer, "┃ {:<38}{:<31}┃", def.name, exts)?;
    }
    writeln!(writer, "{}", row)?;
    writeln!(writer)?;
    Ok(())
}

/// Sorts the given languages in place by the chosen category (descending).
pub fn sort_languages(languages: &mut Vec<(&LanguageType, &Language)>, sort: Sort) {
    match sort {
        Sort::Blanks => languages.sort_by(|a, b| b.1.blanks.cmp(&a.1.blanks)),
        Sort::Comments => languages.sort_by(|a, b| b.1.comments.cmp(&a.1.comments)),
        Sort::Code => languages.sort_by(|a, b| b.1.code.cmp(&a.1.code)),
        Sort::Files => languages.sort_by(|a, b| b.1.reports.len().cmp(&a.1.reports.len())),
        Sort::Lines => languages.sort_by(|a, b| b.1.lines().cmp(&a.1.lines())),
    }
}
