//! Command line interface definition.

use clap::{Arg, ArgAction, ArgMatches, Command};

use crate::cli_utils::NumberFormatStyle;
use crate::config::Config;
use crate::language_type::LanguageType;
use crate::sort::Sort;

pub const VERSION: &str = "14.0.0 compiled with serialization support: json";

const VERBOSE_HELP: &str = "Set log output level:
                          1: to show unknown file extensions,
                          2: reserved for future debugging,
                          3: enable file level trace. Not recommended on multiple files";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Format {
    Json,
}

fn parse_format(s: &str) -> Result<Format, String> {
    match s {
        "json" => Ok(Format::Json),
        other => Err(format!(
            "This version of tokei was compiled without any '{other}' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features {other}\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n"
        )),
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Streaming {
    Simple,
    Json,
}

pub fn build_command(term_width: Option<usize>) -> Command {
    let mut cmd = Command::new("tokei")
        .version(VERSION)
        .about("Count your code, quickly.\nSupport this project on GitHub Sponsors: https://github.com/sponsors/XAMPPRocky")
        .arg(
            Arg::new("columns")
                .long("columns")
                .short('c')
                .value_name("columns")
                .value_parser(clap::value_parser!(usize))
                .conflicts_with("output")
                .help("Sets a strict column width of the output, only available for terminal output."),
        )
        .arg(
            Arg::new("exclude")
                .long("exclude")
                .short('e')
                .value_name("exclude")
                .action(ArgAction::Append)
                .help("Ignore all files & directories matching the pattern."),
        )
        .arg(
            Arg::new("files")
                .long("files")
                .short('f')
                .action(ArgAction::SetTrue)
                .help("Will print out statistics on individual files."),
        )
        .arg(
            Arg::new("file_input")
                .long("input")
                .short('i')
                .value_name("file_input")
                .help("Gives statistics from a previous tokei run. Can be given a file path, or \"stdin\" to read from stdin."),
        )
        .arg(
            Arg::new("hidden")
                .long("hidden")
                .action(ArgAction::SetTrue)
                .help("Count hidden files."),
        )
        .arg(
            Arg::new("languages")
                .long("languages")
                .short('l')
                .action(ArgAction::SetTrue)
                .conflicts_with("input")
                .help("Prints out supported languages and their extensions."),
        )
        .arg(
            Arg::new("no_ignore")
                .long("no-ignore")
                .action(ArgAction::SetTrue)
                .help("Don't respect ignore files (.gitignore, .ignore, etc.). This implies --no-ignore-parent, --no-ignore-dot, and --no-ignore-vcs."),
        )
        .arg(
            Arg::new("no_ignore_parent")
                .long("no-ignore-parent")
                .action(ArgAction::SetTrue)
                .help("Don't respect ignore files (.gitignore, .ignore, etc.) in parent directories."),
        )
        .arg(
            Arg::new("no_ignore_dot")
                .long("no-ignore-dot")
                .action(ArgAction::SetTrue)
                .help("Don't respect .ignore and .tokeignore files, including those in parent directories."),
        )
        .arg(
            Arg::new("no_ignore_vcs")
                .long("no-ignore-vcs")
                .action(ArgAction::SetTrue)
                .help("Don't respect VCS ignore files (.gitignore, .hgignore, etc.) including those in parent directories."),
        )
        .arg(
            Arg::new("output")
                .long("output")
                .short('o')
                .value_name("output")
                .value_parser(parse_format)
                .help("Outputs Tokei in a specific format. Compile with additional features for more format support."),
        )
        .arg(
            Arg::new("streaming")
                .long("streaming")
                .value_name("streaming")
                .value_parser(["simple", "json"])
                .help("prints the (language, path, lines, blanks, code, comments) records as simple lines or as Json for batch processing"),
        )
        .arg(
            Arg::new("sort")
                .long("sort")
                .short('s')
                .value_name("sort")
                .value_parser(["files", "lines", "blanks", "code", "comments"])
                .conflicts_with("rsort")
                .help("Sort languages based on column"),
        )
        .arg(
            Arg::new("rsort")
                .long("rsort")
                .short('r')
                .value_name("rsort")
                .value_parser(["files", "lines", "blanks", "code", "comments"])
                .help("Reverse sort languages based on column"),
        )
        .arg(
            Arg::new("types")
                .long("types")
                .short('t')
                .value_name("types")
                .action(ArgAction::Append)
                .help("Filters output by language type, separated by a comma. i.e. -t=Rust,Markdown"),
        )
        .arg(
            Arg::new("compact")
                .long("compact")
                .short('C')
                .action(ArgAction::SetTrue)
                .help("Do not print statistics about embedded languages."),
        )
        .arg(
            Arg::new("num_format_style")
                .long("num-format")
                .short('n')
                .value_name("num_format_style")
                .value_parser(["commas", "dots", "plain", "underscores"])
                .conflicts_with("output")
                .help("Format of printed numbers, i.e., plain (1234, default), commas (1,234), dots (1.234), or underscores (1_234). Cannot be used with --output."),
        )
        .arg(
            Arg::new("verbose")
                .long("verbose")
                .short('v')
                .action(ArgAction::Count)
                .help(VERBOSE_HELP),
        )
        .arg(
            Arg::new("input")
                .value_name("input")
                .action(ArgAction::Append)
                .conflicts_with("languages")
                .help("The path(s) to the file or directory to be counted. (default current directory)"),
        );
    if let Some(width) = term_width {
        cmd = cmd.term_width(width);
    }
    cmd
}

pub struct Cli {
    pub matches: ArgMatches,
    pub columns: Option<usize>,
    pub files: bool,
    pub hidden: bool,
    pub no_ignore: bool,
    pub no_ignore_parent: bool,
    pub no_ignore_dot: bool,
    pub no_ignore_vcs: bool,
    pub output: Option<Format>,
    pub streaming: Option<Streaming>,
    pub print_languages: bool,
    pub sort: Option<Sort>,
    pub sort_reverse: bool,
    pub types: Option<Vec<LanguageType>>,
    pub compact: bool,
    pub number_format: NumberFormatStyle,
    pub verbose: u64,
}

impl Cli {
    pub fn from_args(term_width: Option<usize>) -> Self {
        let matches = build_command(term_width).get_matches();

        let columns = matches.get_one::<usize>("columns").copied();
        let files = matches.get_flag("files");
        let hidden = matches.get_flag("hidden");
        let no_ignore = matches.get_flag("no_ignore");
        let no_ignore_parent = matches.get_flag("no_ignore_parent");
        let no_ignore_dot = matches.get_flag("no_ignore_dot");
        let no_ignore_vcs = matches.get_flag("no_ignore_vcs");
        let print_languages = matches.get_flag("languages");
        let verbose = matches.get_count("verbose") as u64;
        let compact = matches.get_flag("compact");
        let types = matches.get_many::<String>("types").map(|values| {
            values
                .flat_map(|v| v.split(','))
                .map(|t| t.to_lowercase())
                .filter_map(|t| LanguageType::from_str_name(&t))
                .collect::<Vec<_>>()
        });
        let number_format = matches
            .get_one::<String>("num_format_style")
            .and_then(|s| NumberFormatStyle::from_str(s))
            .unwrap_or(NumberFormatStyle::Plain);
        let output = matches.get_one::<Format>("output").copied();
        let streaming = matches
            .get_one::<String>("streaming")
            .map(|s| match s.as_str() {
                "simple" => Streaming::Simple,
                _ => Streaming::Json,
            });
        let (sort, sort_reverse) = if let Some(s) = matches.get_one::<String>("sort") {
            (Sort::from_str_case_insensitive(s), false)
        } else if let Some(s) = matches.get_one::<String>("rsort") {
            (Sort::from_str_case_insensitive(s), true)
        } else {
            (None, false)
        };

        Cli {
            matches,
            columns,
            files,
            hidden,
            no_ignore,
            no_ignore_parent,
            no_ignore_dot,
            no_ignore_vcs,
            output,
            streaming,
            print_languages,
            sort,
            sort_reverse,
            types,
            compact,
            number_format,
            verbose,
        }
    }

    pub fn input(&self) -> Vec<&str> {
        match self.matches.get_many::<String>("input") {
            Some(values) => values.map(String::as_str).collect(),
            None => vec!["."],
        }
    }

    pub fn file_input(&self) -> Option<&str> {
        self.matches.get_one::<String>("file_input").map(String::as_str)
    }

    pub fn ignored_directories(&self) -> Vec<&str> {
        let mut ignored: Vec<&str> = vec![".git"];
        if let Some(user) = self.matches.get_many::<String>("exclude") {
            ignored.extend(user.map(String::as_str));
        }
        ignored
    }

    /// Overrides the configuration with the command line arguments.
    pub fn override_config(&self, mut config: Config) -> Config {
        config.hidden = if self.hidden { Some(true) } else { config.hidden };
        config.no_ignore = if self.no_ignore { Some(true) } else { config.no_ignore };
        config.no_ignore_parent = if self.no_ignore_parent {
            Some(true)
        } else {
            config.no_ignore_parent
        };
        config.no_ignore_dot = if self.no_ignore_dot {
            Some(true)
        } else {
            config.no_ignore_dot
        };
        config.no_ignore_vcs = if self.no_ignore_vcs {
            Some(true)
        } else {
            config.no_ignore_vcs
        };
        config.types = self.types.clone().or(config.types);
        config.columns = self.columns.or(config.columns);
        config.sort = self.sort.or(config.sort);
        config
    }
}
