//! Handling of the `--input` option: a previous run's JSON output.

use std::io::Read;

use serde_json::Value;

use crate::language::Languages;
use crate::language_type::LanguageType;

/// Validates a serialised `CodeStats` object.
fn validate_stats(value: &Value) -> Option<()> {
    let obj = value.as_object()?;
    obj.get("blanks")?.as_u64()?;
    obj.get("code")?.as_u64()?;
    obj.get("comments")?.as_u64()?;
    let blobs = obj.get("blobs")?.as_object()?;
    for (key, stats) in blobs {
        LanguageType::deserialize_name(key)?;
        validate_stats(stats)?;
    }
    Some(())
}

fn validate_reports(value: &Value) -> Option<()> {
    for report in value.as_array()? {
        let obj = report.as_object()?;
        obj.get("name")?.as_str()?;
        validate_stats(obj.get("stats")?)?;
    }
    Some(())
}

fn validate_language(value: &Value) -> Option<()> {
    let obj = value.as_object()?;
    obj.get("blanks")?.as_u64()?;
    obj.get("code")?.as_u64()?;
    obj.get("comments")?.as_u64()?;
    validate_reports(obj.get("reports")?)?;
    let children = obj.get("children")?.as_object()?;
    for (key, reports) in children {
        LanguageType::deserialize_name(key)?;
        validate_reports(reports)?;
    }
    obj.get("inaccurate")?.as_bool()?;
    Some(())
}

fn convert_input(contents: &[u8]) -> Option<()> {
    if contents.is_empty() {
        return None;
    }
    let value: Value = serde_json::from_slice(contents).ok()?;
    let obj = value.as_object()?;
    let total = obj.get("Total")?;
    validate_language(total)?;
    for (key, language) in obj {
        if key == "Total" {
            continue;
        }
        LanguageType::deserialize_name(key)?;
        validate_language(language)?;
    }
    Some(())
}

/// Returns `true` if the input could be parsed. Parsed statistics are not
/// merged into the results (matching the reference behaviour).
pub fn add_input(input: &str, _languages: &mut Languages) -> bool {
    let contents = match std::fs::read(input) {
        Ok(contents) => contents,
        Err(_) => {
            if input == "stdin" {
                let mut buffer = Vec::new();
                let _ = std::io::stdin().read_to_end(&mut buffer);
                buffer
            } else {
                return false;
            }
        }
    };
    convert_input(&contents).is_some()
}

pub fn print_input_parse_failure(input: &str) {
    eprintln!(
        r#"Error:
 Failed to parse input file: {}

This version of tokei was compiled without serialization support for the following formats:

    cbor, json, yaml

You may want to install any comma separated combination of "cbor,json,yaml":

    cargo install tokei --features "cbor,json,yaml"

Or use the 'all' feature:

    cargo install tokei --features all

"#,
        input
    );
}
