//! JSON serialisation of the results.

use std::fmt::Write;

use crate::language::{total, Language, Languages};
use crate::language_type::LanguageType;
use crate::stats::{CodeStats, Report};

fn json_str(s: &str) -> String {
    serde_json::to_string(s).unwrap_or_else(|_| "\"\"".to_string())
}

fn write_stats(out: &mut String, stats: &CodeStats) {
    write!(
        out,
        "{{\"blanks\":{},\"code\":{},\"comments\":{},\"blobs\":{{",
        stats.blanks, stats.code, stats.comments
    )
    .unwrap();
    let mut first = true;
    for (language, blob) in &stats.blobs {
        if !first {
            out.push(',');
        }
        first = false;
        out.push_str(&json_str(language.name()));
        out.push(':');
        write_stats(out, blob);
    }
    out.push_str("}}");
}

fn write_report(out: &mut String, report: &Report) {
    out.push_str("{\"stats\":");
    write_stats(out, &report.stats);
    out.push_str(",\"name\":");
    out.push_str(&json_str(&report.name.to_string_lossy()));
    out.push('}');
}

fn write_reports(out: &mut String, reports: &[Report]) {
    out.push('[');
    for (i, report) in reports.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        write_report(out, report);
    }
    out.push(']');
}

fn write_language(out: &mut String, language: &Language) {
    write!(
        out,
        "{{\"blanks\":{},\"code\":{},\"comments\":{},\"reports\":",
        language.blanks, language.code, language.comments
    )
    .unwrap();
    write_reports(out, &language.reports);
    out.push_str(",\"children\":{");
    let mut first = true;
    for (language_type, reports) in &language.children {
        if !first {
            out.push(',');
        }
        first = false;
        out.push_str(&json_str(language_type.name()));
        out.push(':');
        write_reports(out, reports);
    }
    write!(out, "}},\"inaccurate\":{}}}", language.inaccurate).unwrap();
}

/// Serialises all languages (plus the `Total` entry) to JSON.
pub fn languages_to_json(languages: &Languages, sorted: Option<&[(&LanguageType, &Language)]>) -> String {
    let mut out = String::new();
    out.push('{');
    let mut first = true;
    let mut emit = |out: &mut String, language_type: &LanguageType, language: &Language| {
        if !first {
            out.push(',');
        }
        first = false;
