    for (language, blob) in &stats.blobs {
        if !first {
            out.push(',');
        }
        first = false;
        out.push_str(&json_str(language.name()));
        out.push(':');
        write_stats(out, blob);
    }
    out.push_str("}}");
}

fn write_report(out: &mut String, report: &Report) {
    out.push_str("{\"stats\":");
    write_stats(out, &report.stats);
    out.push_str(",\"name\":");
    out.push_str(&json_str(&report.name.to_string_lossy()));
    out.push('}');
}

fn write_reports(out: &mut String, reports: &[Report]) {
    out.push('[');
    for (i, report) in reports.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        write_report(out, report);
    }
    out.push(']');
}

fn write_language(out: &mut String, language: &Language) {
