use std::io::{self, Write};
use std::process;

use cli::{Cli, Streaming};
use cli_utils::{print_supported_languages, sort_languages, Printer, FALLBACK_ROW_LEN};
use config::Config;
use language::Languages;

/// Width of the terminal, if any of the standard streams is a terminal.
fn terminal_width() -> Option<usize> {
    for fd in [libc::STDOUT_FILENO, libc::STDIN_FILENO, libc::STDERR_FILENO] {
        let mut size: libc::winsize = unsafe { std::mem::zeroed() };
        let r = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut size) };
        if r == 0 && size.ws_col > 0 {
            return Some(size.ws_col as usize);
        }
    }
    None
}

fn main() {
    if let Err(error) = run() {
        if error.kind() == io::ErrorKind::BrokenPipe {
            process::exit(0);
        }
        eprintln!("Error: {}", error);
        process::exit(1);
    }
}

fn run() -> io::Result<()> {
    let term_width = terminal_width();
    let cli = Cli::from_args(term_width);

    let log_level = match cli.verbose {
        0 => log::LevelFilter::Error,
        1 => log::LevelFilter::Warn,
        2 => log::LevelFilter::Debug,
        _ => log::LevelFilter::Trace,
    };
    logger::init(log_level);

    if cli.print_languages {
        let stdout = io::stdout();
        let mut out = io::BufWriter::new(stdout.lock());
        print_supported_languages(&mut out)?;
        return out.flush();
    }

    let config = cli.override_config(Config::from_config_files());
    log::debug!("CLI Config: {:?}", config);

    let mut languages = Languages::new();

    if let Some(input) = cli.file_input() {
        if !input::add_input(input, &mut languages) {
            input::print_input_parse_failure(input);
            process::exit(1);
        }
    }

    let input = cli.input();
    for path in &input {
        if std::fs::metadata(path).is_err() {
            eprintln!("Error: '{}' not found.", path);
            process::exit(1);
        }
    }

    let columns = cli
        .columns
        .or(config.columns)
        .or(term_width)
        .unwrap_or(FALLBACK_ROW_LEN)
        .max(FALLBACK_ROW_LEN);

    let streaming = cli.streaming;
    if streaming == Some(Streaming::Simple) {
        println!(
            "#{:^10} {:^80} {:^12} {:^12} {:^12} {:^12}",
            "language", "path", "lines", "code", "comments", "blanks"
        );
        println!(
            "{:>10} {:>80} {:>12} {:>12} {:>12} {:>12}",
            "#".repeat(10),
            "#".repeat(80),
            "#".repeat(12),
            "#".repeat(12),
            "#".repeat(12),
            "#".repeat(12)
        );
    }

    let for_each_fn: Option<Box<dyn Fn(language_type::LanguageType, &stats::Report) + Sync>> =
        match streaming {
            Some(Streaming::Simple) => Some(Box::new(|language, report| {
                let name = report.name.to_string_lossy();
                let line = format!(
                    "{:>10} {:<80} {:>12} {:>12} {:>12} {:>12}",
                    language.name(),
                    name,
                    report.stats.lines(),
                    report.stats.code,
                    report.stats.comments,
                    report.stats.blanks
                );
                let stdout = io::stdout();
                let mut lock = stdout.lock();
                let _ = writeln!(lock, "{}", line);
            })),
            Some(Streaming::Json) => Some(Box::new(|language, report| {
                let line = output::streaming_json(language, report);
                let stdout = io::stdout();
                let mut lock = stdout.lock();
                let _ = writeln!(lock, "{}", line);
            })),
            None => None,
        };

    let ignored = cli.ignored_directories();
    utils::fs::get_all_files(
        &input,
        &ignored,
        &mut languages,
        &config,
        for_each_fn.as_deref(),
    );

    if streaming.is_some() {
        return Ok(());
    }

    let sorted: Option<Vec<(&language_type::LanguageType, &language::Language)>> =
        if let Some(sort_category) = cli.sort.or(config.sort) {
            for language in languages.values_mut() {
                language.sort_by(sort_category);
            }
            None
        } else {
            None
        };
    drop(sorted);

    if let Some(_format) = cli.output {
        let sorted_list;
        let list: Option<&[(&language_type::LanguageType, &language::Language)]> =
            if let Some(sort_category) = cli.sort.or(config.sort) {
                let mut l: Vec<_> = languages.iter().collect();
                sort_languages(&mut l, sort_category);
                if cli.sort_reverse {
                    l.reverse();
                }
                sorted_list = l;
                Some(&sorted_list)
            } else {
                None
            };
        let json = output::languages_to_json(&languages, list);
        let stdout = io::stdout();
        let mut lock = stdout.lock();
        write!(lock, "{}", json)?;
        return lock.flush();
    }

    let stdout = io::stdout();
    let mut printer = Printer::new(
        columns,
        cli.files,
        io::BufWriter::new(stdout.lock()),
        cli.number_format,
    );

    if languages.values().any(|l| l.inaccurate) {
        printer.print_inaccuracy_warning()?;
    }

    printer.print_header()?;

    if let Some(sort_category) = cli.sort.or(config.sort) {
        let mut list: Vec<_> = languages.iter().collect();
        sort_languages(&mut list, sort_category);
        if cli.sort_reverse {
            list.reverse();
        }
        printer.print_results(list.into_iter(), cli.compact, true)?;
    } else {
        printer.print_results(languages.iter(), cli.compact, false)?;
    }

    printer.print_total(&languages)?;
    printer.flush()
}
