/// Files starting with a byte order mark are transcoded to UTF-8; all other
/// files are used as they are.
pub fn decode_bom(bytes: Vec<u8>) -> Vec<u8> {
    if bytes.starts_with(&[0xEF, 0xBB, 0xBF]) {
        String::from_utf8_lossy(&bytes[3..]).into_owned().into_bytes()
    } else if bytes.starts_with(&[0xFF, 0xFE]) {
        decode_utf16(&bytes[2..], true)
    } else if bytes.starts_with(&[0xFE, 0xFF]) {
        decode_utf16(&bytes[2..], false)
    } else {
        bytes
    }
}

fn decode_utf16(bytes: &[u8], little_endian: bool) -> Vec<u8> {
    let mut units: Vec<u16> = bytes
        .chunks_exact(2)
        .map(|c| {
            if little_endian {
                u16::from_le_bytes([c[0], c[1]])
            } else {
                u16::from_be_bytes([c[0], c[1]])
            }
        })
        .collect();
    let odd_tail = bytes.len() % 2 == 1;
    let mut out = String::with_capacity(units.len());
    let mut i = 0;
    while i < units.len() {
        let u = units[i];
        if (0xD800..0xDC00).contains(&u) {
            if i + 1 < units.len() && (0xDC00..0xE000).contains(&units[i + 1]) {
                let c = 0x10000 + (((u as u32) - 0xD800) << 10) + ((units[i + 1] as u32) - 0xDC00);
                out.push(char::from_u32(c).unwrap_or('\\u{FFFD}'));
                i += 2;
                continue;
            }
            out.push('\\u{FFFD}');
        } else if (0xDC00..0xE000).contains(&u) {
            out.push('\\u{FFFD}');
        } else {
            out.push(char::from_u32(u as u32).unwrap_or('\\u{FFFD}'));
        }
        i += 1;
    }
    if odd_tail {
        out.push('\\u{FFFD}');
    }
    units.clear();
    out.into_bytes()
}'''
